import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';
import{population,circleArea,clearRingArea,zoneRuns,culturePlanValid,growthAssumptions}from './culture-models.js?v=20261023-physicscomplete01';
import{cultureFigure,growthFigure,zoneFigure}from './culture-figures.js?v=20261023-physicscomplete01';
const opts=(items,v)=>'<option value="">Choose…</option>'+items.map(([k,t])=>`<option value="${k}"${String(v)===k?' selected':''}>${t}</option>`).join('');
export function showCulture(kind='agar',w={}){const medium=w.medium||(kind==='broth'?'broth':'agar');renderCustomModel({name:medium==='broth'?'Nutrient broth':'Nutrient agar plate',formula:w.inverted?'Inverted plate':'Compare culture media',kicker:'SCHEMATIC CULTURE · SCHOOL PREPARATION',atoms:[],bonds:[],radius:3,viewKey:'culture:'+medium,startPaused:true,note:'Model only · sterility and safety need real controls',aria:medium+' culture model. '+(w.inverted?'Plate inverted.':'Plate upright.')+' Sterility and lid choices are in the labelled controls.',diagram:cultureFigure({...w,medium})+'<p class="diagram-caption">Conceptual equipment view, not a culture protocol or a prediction of contamination. Real school work uses approved organisms, teacher supervision and risk assessment. Incubated plates stay closed for measurements.</p>',build:(g,T)=>{const glass=new T.MeshStandardMaterial({color:0xd4dfe7,transparent:true,opacity:.18,roughness:.2,depthWrite:false});if(medium==='broth'){const bottle=new T.Mesh(new T.CylinderGeometry(.72,.85,2.8,48),glass);g.add(bottle);const liquid=new T.Mesh(new T.CylinderGeometry(.67,.8,1.3,48),new T.MeshStandardMaterial({color:0xed8b78,transparent:true,opacity:.5,roughness:.3}));liquid.position.y=-.65;g.add(liquid);const cap=new T.Mesh(new T.CylinderGeometry(.75,.75,.2,48),new T.MeshStandardMaterial({color:0x526f86}));cap.position.y=1.5;g.add(cap);}else{const plate=new T.Group(),base=new T.Mesh(new T.CylinderGeometry(2.05,2.05,.18,64),glass);plate.add(base);const agar=new T.Mesh(new T.CylinderGeometry(1.95,1.95,.08,64),new T.MeshStandardMaterial({color:0xed8b78,roughness:.32,transparent:true,opacity:.55}));agar.position.y=.1;plate.add(agar);const lid=new T.Mesh(new T.CylinderGeometry(2.12,2.12,.12,64),glass);lid.position.y=.35;plate.add(lid);for(let i=0;i<9;i++){const colony=new T.Mesh(new T.SphereGeometry(.08,16,12),new T.MeshStandardMaterial({color:0xf8f6f2,roughness:.3}));colony.scale.y=.3;colony.position.set(Math.cos(i*2.4)*(i%3+1)*.42,.16,Math.sin(i*2.4)*(i%3+1)*.42);plate.add(colony);}if(w.tape==='strips')for(const x of[-1.8,1.8]){const tape=new T.Mesh(new T.BoxGeometry(.25,.7,.5),new T.MeshStandardMaterial({color:0xb7c8d6,transparent:true,opacity:.7}));tape.position.set(x,.18,0);plate.add(tape);}plate.rotation.x=.55+(w.inverted?Math.PI:0);g.add(plate);}}});}
export function showGrowth(step=0,w={}){renderDiagram('Binary-fission model','Each complete division doubles the population',growthFigure({initial:w.initial??2,step:Number(step)||0,division:w.division??20,supported:w.supported!==false})+'<p class="diagram-caption">A supplied constant mean division time assumes suitable conditions and nutrients, with no deaths or resource limit. Real cultures do not double indefinitely. Cell symbols and time steps are schematic.</p>','COUNT COMPLETE DOUBLINGS');}
export function showZone(kind='measure',w={}){renderDiagram('Measure the inhibition zone',kind==='compare'?'Compare original illustrative results':'Measure across the whole clear circle',zoneFigure({diameter:w.diameter??20,disc:6,otherDiameter:kind==='measure'?22:(w.diameter??20),axis:w.axis??0,start:w.start??0,end:w.end??0})+'<p class="diagram-caption">Schematic closed plate and ruler, not live growth or a calibrated screen measurement. The clear-zone measurement includes the disc unless an annular area is explicitly requested. A larger zone is not evidence of a clinical cure.</p>','MEASUREMENT · AREA · EVIDENCE');}
export function mountCulture(l,p,root,{save,done,feedback}){const w=p.widget,$=s=>root.querySelector(s),mode=l.widget,total=mode==='culture-lab'?4:3;w.task??=0;w.passed??=[];const task=w.task%total,tail='<button class="secondary" id="checkCulture">Check reasoning</button><button class="secondary" id="nextCulture">Next challenge →</button><p id="cultureProgress">'+w.passed.length+' / '+total+' complete</p>';const finish=()=>{if(!w.passed.includes(task))w.passed.push(task);if(w.passed.length===total){p.widgetDone=true;save();done();}save();$('#cultureProgress').textContent=w.passed.length+' / '+total+' complete';};
if(mode==='culture-lab'){
if(task===0){w.medium??='agar';w.mediaSeen??=[];root.innerHTML='<p><b>1 / 4 · Compare media</b></p><p>Switch between broth and agar. Observe each and explain where separate visible colonies can form.</p><label class="field-label" for="cultureMedium">Medium</label><select id="cultureMedium" class="lab-select">'+opts([['agar','Nutrient agar'],['broth','Nutrient broth']],w.medium)+'</select><button class="secondary" id="observeMedium">Observe medium</button><label class="field-label" for="cultureMediumReason">Visible colonies grow on…</label><select id="cultureMediumReason" class="lab-select">'+opts([['agar','Agar gel surface'],['both','Only the bottle lid'],['none','No culture medium']],w.mediumReason)+'</select>'+tail;$('#cultureMedium').onchange=e=>{w.medium=e.target.value;save();showCulture(w.medium,w);};$('#observeMedium').onclick=()=>{if(!w.mediaSeen.includes(w.medium))w.mediaSeen.push(w.medium);save();feedback(w.medium==='agar'?'Agar is a gel surface supporting visible colonies.':'Broth is a nutrient solution containing suspended cells.');};$('#cultureMediumReason').onchange=e=>{w.mediumReason=e.target.value;save();};$('#checkCulture').onclick=()=>{if(!['agar','broth'].every(v=>w.mediaSeen.includes(v))||w.mediumReason!=='agar'){feedback('Observe broth and agar, then distinguish suspended growth from visible colonies on a surface.',true);return;}finish();feedback('Both can supply nutrients; agar supports separate visible colonies.');};showCulture(w.medium,w);
}else if(task===1){root.innerHTML='<p><b>2 / 4 · Explain aseptic controls</b></p><p>Choose the equipment states for an uncontaminated school culture. These controls reduce contamination; a model cannot certify sterility.</p>'+[['media','Petri dish and culture medium'],['loop','Inoculating loop before transfer']].map(([key,label])=>'<label class="field-label" for="culture-'+key+'">'+label+'</label><select id="culture-'+key+'" class="lab-select">'+opts([['uncertain','Not sterilised'],['sterile','Sterilised as required']],w[key]||'uncertain')+'</select>').join('')+'<label class="field-label" for="sterileReason">Why sterilise the dish and medium?</label><select id="sterileReason" class="lab-select">'+opts([['kill','Kill unwanted microorganisms'],['feed','Add nutrients only'],['colour','Change colour']],w.sterileReason)+'</select><label class="field-label" for="loopReason">Why is the loop passed through a flame?</label><select id="loopReason" class="lab-select">'+opts([['kill','Kill unwanted microorganisms'],['warm','Make nutrients warmer'],['multiply','Multiply bacteria on the loop']],w.loopReason)+'</select><p id="asepticStatus" aria-live="polite"></p>'+tail;const draw=()=>{$('#asepticStatus').textContent='Media control: '+(w.media||'uncertain')+' · loop control: '+(w.loop||'uncertain');showCulture('aseptic',w);};for(const key of['media','loop'])$('#culture-'+key).onchange=e=>{w[key]=e.target.value;save();draw();};for(const key of['sterileReason','loopReason'])$('#'+key).onchange=e=>{w[key]=e.target.value;save();};$('#checkCulture').onclick=()=>{if(w.media!=='sterile'||w.loop!=='sterile'||w.sterileReason!=='kill'||w.loopReason!=='kill'){feedback('Sterilising the dish/media and flaming the loop kill unwanted microorganisms, reducing contamination that would invalidate the intended comparison.',true);return;}finish();feedback('Uncontaminated cultures are needed to investigate disinfectants and antibiotics fairly.');};draw();
}else if(task===2){w.medium='agar';root.innerHTML='<p><b>3 / 4 · Lid and storage</b></p><label class="field-label" for="cultureTape">Lid securing method</label><select id="cultureTape" class="lab-select">'+opts([['none','Unsecured lid'],['strips','Small tape strips'],['sealed','Sealed all the way around']],w.tape||'none')+'</select><label class="field-label" for="culturePosition">Storage position</label><select id="culturePosition" class="lab-select">'+opts([['upright','Upright'],['inverted','Inverted']],w.inverted?'inverted':'upright')+'</select><label class="field-label" for="cultureStorageReason">Why invert the plate?</label><select id="cultureStorageReason" class="lab-select">'+opts([['drops','Keep condensation off agar'],['oxygen','Remove all oxygen'],['heat','Raise temperature']],w.storageReason)+'</select><p id="storageStatus" aria-live="polite"></p>'+tail;const draw=()=>{showCulture('agar',w);$('#storageStatus').textContent=(w.inverted?'Condensation is kept away from the agar.':'Condensation may drip onto agar.')+' '+(w.tape==='sealed'?'Complete sealing can create anaerobic conditions.':'Secure tape strips help keep the lid in place.');};$('#cultureTape').onchange=e=>{w.tape=e.target.value;save();draw();};$('#culturePosition').onchange=e=>{w.inverted=e.target.value==='inverted';save();draw();};$('#cultureStorageReason').onchange=e=>{w.storageReason=e.target.value;save();};$('#checkCulture').onclick=()=>{if(w.tape!=='strips'||!w.inverted||w.storageReason!=='drops'){feedback('Secure the lid using strips, not an all-round seal. Invert to keep condensation from dripping onto the agar. Measure incubated cultures with the lid closed.',true);return;}finish();feedback('Lid secured; condensation kept off agar. This is preparation reasoning, not a real aseptic-technique assessment.');};draw();
}else{root.innerHTML='<p><b>4 / 4 · School temperature limit</b></p><label class="field-label" for="cultureTemperature">School incubation choice / °C</label><select id="cultureTemperature" class="lab-select">'+opts([['20','20'],['25','25'],['37','37']],String(w.temperature??25))+'</select><label class="field-label" for="cultureTemperatureReason">Why a maximum of25°C in school?</label><select id="cultureTemperatureReason" class="lab-select">'+opts([['risk','Reduce harmful-microbe risk'],['sterile','It sterilises every organism'],['fastest','It is always the fastest growth']],w.temperatureReason)+'</select><button class="secondary" id="validateCulturePlan">Evaluate school plan</button><p id="temperatureStatus" aria-live="polite"></p>'+tail;$('#cultureTemperature').onchange=e=>{w.temperature=Number(e.target.value);w.planChecked=false;$('#temperatureStatus').textContent='Evaluate the changed plan.';save();showCulture('agar',w);};$('#cultureTemperatureReason').onchange=e=>{w.temperatureReason=e.target.value;save();};$('#validateCulturePlan').onclick=()=>{w.temperature??=25;w.planChecked=true;save();$('#temperatureStatus').textContent=culturePlanValid(w)?'The selected school controls satisfy this model’s plan checks.':'School plan rejected: check the maximum25°C and prior aseptic/lid choices.';feedback($('#temperatureStatus').textContent,!culturePlanValid(w));};$('#checkCulture').onclick=()=>{if(!w.planChecked||!culturePlanValid(w)||w.temperatureReason!=='risk'){feedback('Use a maximum of25°C for school cultures to reduce the risk of growing harmful organisms. It does not sterilise the culture or guarantee safety.',true);return;}finish();feedback('School practical work still needs approved organisms, supervision and a full risk assessment.');};showCulture('agar',w);}
}else if(mode==='growth-lab'){
if(task===0){w.growthStep??=0;root.innerHTML='<p><b>1 / 3 · Follow complete divisions</b></p><p>Supplied model:2 bacteria initially, one complete division every20 minutes for60 minutes. Assume sufficient nutrients, suitable conditions and no deaths.</p><label class="field-label" for="growthPrediction">Predict the population after60 minutes</label><input id="growthPrediction" class="lab-input" type="number" value="'+(w.growthPrediction??'')+'"><button class="secondary" id="stepGeneration">Step one division →</button><p id="growthStatus" aria-live="polite"></p>'+tail;const draw=()=>{showGrowth(w.growthStep,{initial:2,division:20});$('#growthStatus').textContent='Divisions '+w.growthStep+' · population '+population(2,w.growthStep)+' · time '+w.growthStep*20+' minutes';};$('#growthPrediction').oninput=e=>{w.growthPrediction=e.target.value;save();};$('#stepGeneration').onclick=()=>{if(String(w.growthPrediction??'').trim()===''){feedback('Predict before stepping the divisions.',true);return;}w.growthStep=Math.min(3,w.growthStep+1);save();draw();};$('#checkCulture').onclick=()=>{if(w.growthStep!==3||Number(w.growthPrediction)!==16){feedback('60÷20 gives3 complete divisions. Starting2 cells double to4,8,16; add no fixed number per generation.',true);return;}finish();feedback('Binary fission doubles each existing cell. The total is2 ×2³=16 in this supplied model.');};draw();
}else if(task===1){w.division??=20;w.compareSteps??={20:0,40:0};root.innerHTML='<p><b>2 / 3 · Compare supplied mean division times</b></p><p>Start with1 cell for120 minutes. Compare20-minute and40-minute division times. These are supplied scenarios, not a temperature-response experiment.</p><label class="field-label" for="divisionTime">Supplied mean division time</label><select id="divisionTime" class="lab-select">'+opts([['20','20 minutes'],['40','40 minutes']],String(w.division))+'</select><button class="secondary" id="stepGrowthComparison">Step one complete division →</button>'+[['growth20','Predicted population:20-minute case'],['growth40','Predicted population:40-minute case']].map(([key,label])=>'<label class="field-label" for="'+key+'">'+label+'</label><input id="'+key+'" class="lab-input" type="number" value="'+(w[key]??'')+'">').join('')+'<p id="growthCompareStatus" aria-live="polite"></p>'+tail;const draw=()=>{showGrowth(w.compareSteps[w.division],{initial:1,division:w.division});$('#growthCompareStatus').textContent='20-minute case: '+w.compareSteps[20]+' /6 divisions;40-minute case: '+w.compareSteps[40]+' /3 divisions.';};$('#divisionTime').onchange=e=>{w.division=Number(e.target.value)||20;save();draw();};for(const key of['growth20','growth40'])$('#'+key).oninput=e=>{w[key]=e.target.value;save();};$('#stepGrowthComparison').onclick=()=>{if(String(w.growth20??'').trim()===''||String(w.growth40??'').trim()===''){feedback('Predict both populations before comparing.',true);return;}w.compareSteps[w.division]=Math.min(120/w.division,w.compareSteps[w.division]+1);save();draw();};$('#checkCulture').onclick=()=>{if(w.compareSteps[20]!==6||w.compareSteps[40]!==3||Number(w.growth20)!==64||Number(w.growth40)!==8){feedback('Use number of complete divisions=time÷division time, then starting population ×2 to that power. Step both complete comparisons.',true);return;}finish();feedback('Six divisions give64; three give8. Doubling the division time does not merely halve the final population.');};draw();
}else{w.nutrients??='enough';w.conditions??='suitable';w.assumptionStates??=[];root.innerHTML='<p><b>3 / 3 · Test the model assumptions</b></p><label class="field-label" for="growthNutrients">Nutrient availability</label><select id="growthNutrients" class="lab-select">'+opts([['enough','Enough nutrients'],['limited','Nutrients limiting']],w.nutrients)+'</select><label class="field-label" for="growthConditions">Conditions</label><select id="growthConditions" class="lab-select">'+opts([['suitable','Suitable conditions'],['unsuitable','Unsuitable conditions']],w.conditions)+'</select><button class="secondary" id="observeGrowthAssumptions">Evaluate prediction</button><label class="field-label" for="growthLimitReason">Can the population double forever at a constant rate?</label><select id="growthLimitReason" class="lab-select">'+opts([['no','No; resources and conditions limit it'],['yes','Yes, under every condition'],['zero','No; every cell is already dead']],w.limitReason)+'</select><p id="assumptionStatus" aria-live="polite"></p>'+tail;const draw=()=>showGrowth(3,{initial:1,division:20,supported:growthAssumptions(w)});for(const[id,key]of[['growthNutrients','nutrients'],['growthConditions','conditions']])$('#'+id).onchange=e=>{w[key]=e.target.value;save();draw();};$('#growthLimitReason').onchange=e=>{w.limitReason=e.target.value;save();};$('#observeGrowthAssumptions').onclick=()=>{const supported=growthAssumptions(w),key=supported?'supported':'limited';if(!w.assumptionStates.includes(key))w.assumptionStates.push(key);save();$('#assumptionStatus').textContent=supported?'Constant doubling is the supplied ideal assumption, not a universal growth law.':'The constant doubling prediction is unsupported. This does not determine an exact new division time or population.';draw();};$('#checkCulture').onclick=()=>{if(!['supported','limited'].every(k=>w.assumptionStates.includes(k))||w.limitReason!=='no'){feedback('Evaluate both suitable/sufficient and a limiting case, then explain why constant doubling is conditional.',true);return;}finish();feedback('Some bacteria can divide as often as every20 minutes under suitable conditions; it is not universal or unlimited.');};draw();}
}else{
if(task===0){w.axis??=0;w.rulerStart??=0;w.rulerEnd??=0;w.measured??={};root.innerHTML='<p><b>1 / 3 · Measure two diameters</b></p><p>Use the model ruler through the centre. Set both clear-zone edges, record, then rotate90°. The disc is6 mm; measure the whole clear zone, not only the disc.</p><label class="field-label" for="zoneAxis">Measurement axis</label><select id="zoneAxis" class="lab-select">'+opts([['0','First diameter'],['90','Perpendicular diameter']],String(w.axis))+'</select>'+[['zoneStart','First edge',w.rulerStart],['zoneEnd','Second edge',w.rulerEnd]].map(([id,label,v])=>'<label class="field-label" for="'+id+'">'+label+' /mm</label><input id="'+id+'" type="range" min="0" max="40" step="1" value="'+v+'">').join('')+'<button class="secondary" id="recordZoneMeasurement">Record diameter</button><p id="zoneReadout" aria-live="polite"></p><label class="field-label" for="zoneMean">Mean diameter /mm</label><input id="zoneMean" class="lab-input" type="number" step="any" value="'+(w.zoneMean??'')+'"><label class="field-label" for="zoneArea">Full circular area from mean diameter /mm²</label><input id="zoneArea" class="lab-input" type="number" step="any" value="'+(w.zoneArea??'')+'">'+tail;const draw=()=>{showZone('measure',{diameter:20,axis:w.axis,start:w.rulerStart,end:w.rulerEnd});$('#zoneReadout').textContent='Edges '+w.rulerStart+' to'+w.rulerEnd+' mm · span '+(w.rulerEnd-w.rulerStart)+' mm. Recorded first '+(w.measured[0]??'—')+'; perpendicular '+(w.measured[90]??'—')+'.';};$('#zoneAxis').onchange=e=>{w.axis=Number(e.target.value)||0;save();draw();};for(const[id,key]of[['zoneStart','rulerStart'],['zoneEnd','rulerEnd']])$('#'+id).oninput=e=>{w[key]=Number(e.target.value);save();draw();};$('#recordZoneMeasurement').onclick=()=>{const diameter=w.axis===90?22:20;if(w.rulerStart!==20-diameter/2||w.rulerEnd!==20+diameter/2){feedback('Align the two markers with the outer clear-zone edges along the diameter through its centre.',true);return;}w.measured[w.axis]=w.rulerEnd-w.rulerStart;save();draw();};for(const key of['zoneMean','zoneArea'])$('#'+key).oninput=e=>{w[key]=e.target.value;save();};$('#checkCulture').onclick=()=>{if(w.measured[0]!==20||w.measured[90]!==22||Number(w.zoneMean)!==21||String(w.zoneArea??'').trim()===''||Math.abs(Number(w.zoneArea)-circleArea(21))>1){feedback('Measure20 and22 mm on perpendicular axes. Mean21 mm gives radius10.5 mm; use πr². Full clear-circle area includes the disc for this question.',true);return;}finish();feedback('Mean diameter21 mm; full circular area about346.4 mm². The circular area from a mean diameter approximates an irregular real zone.');};draw();
}else if(task===1){root.innerHTML='<p><b>2 / 3 · Compare repeats and control</b></p><p>Original illustrative diameters /mm: A18,20,22; B12,14,16; solvent control6,6,6. All discs6 mm; organism, agar, treatment amount and other conditions matched.</p><label class="field-label" for="zoneTreatment">Inspect treatment</label><select id="zoneTreatment" class="lab-select">'+opts(zoneRuns.map(r=>[r.id,r.name]),w.zoneTreatment||'A')+'</select><label class="field-label" for="zoneCompareReason">Supported conclusion</label><select id="zoneCompareReason" class="lab-select">'+opts([['A','A has greater inhibition here'],['cure','A cures every human infection'],['control','The solvent caused all inhibition']],w.compareReason)+'</select><button class="secondary" id="observeZoneTreatment">Record observation</button>'+tail;w.treatmentsSeen??=[];const draw=()=>{const r=zoneRuns.find(r=>r.id===(w.zoneTreatment||'A'));showZone('compare',{diameter:r.diameters[1]});};$('#zoneTreatment').onchange=e=>{w.zoneTreatment=e.target.value;save();draw();};$('#observeZoneTreatment').onclick=()=>{const k=w.zoneTreatment||'A';if(!w.treatmentsSeen.includes(k))w.treatmentsSeen.push(k);save();feedback('Inspect all treatments, including the solvent control.');};$('#zoneCompareReason').onchange=e=>{w.compareReason=e.target.value;save();};$('#checkCulture').onclick=()=>{if(!['A','B','control'].every(k=>w.treatmentsSeen.includes(k))||w.compareReason!=='A'){feedback('Compare repeated measurements and the solvent control. Greater inhibition in this agar test does not establish a clinical cure or distinguish all possible causes.',true);return;}finish();feedback('A has a larger mean zone in these matched conditions; repeats and the control strengthen the comparison.');};draw();
}else{root.innerHTML='<p><b>3 / 3 · Distinguish a disc from a ring</b></p><p>A different supplied plate has a circular outer clear diameter20 mm and disc diameter6 mm. This question explicitly asks for the CLEAR ANNULAR AREA outside the disc.</p><label class="field-label" for="zoneRingArea">Annular area /mm²</label><input id="zoneRingArea" class="lab-input" type="number" step="any" value="'+(w.ringArea??'')+'"><label class="field-label" for="zoneEvidence">What does a clear zone show?</label><select id="zoneEvidence" class="lab-select">'+opts([['inhibited','Visible growth inhibited here'],['killed','Every cell certainly killed'],['cured','Clinical cure established']],w.evidence)+'</select>'+tail;$('#zoneRingArea').oninput=e=>{w.ringArea=e.target.value;save();};$('#zoneEvidence').onchange=e=>{w.evidence=e.target.value;save();};$('#checkCulture').onclick=()=>{if(String(w.ringArea??'').trim()===''||Math.abs(Number(w.ringArea)-clearRingArea(20,6))>1||w.evidence!=='inhibited'){feedback('Only because this question requests the ring, subtract the disc area: π10²−π3²≈285.9 mm². Inhibited visible growth does not prove all cells were killed or a patient would be cured.',true);return;}finish();feedback('About285.9 mm² outside the disc. Follow the area definition in the question; do not subtract the disc automatically.');};showZone('evaluate',{diameter:20});}
}
$('#nextCulture').onclick=()=>{if(!w.passed.includes(task)){feedback('Complete this challenge first.',true);return;}w.task=(task+1)%total;save();feedback('');mountCulture(l,p,root,{save,done,feedback});};}
